//! Monospace bitmap fonts: ASCII in 4-bit alpha (generated by
//! `tools/gen_font.py`), Korean and other non-ASCII glyphs in 2-bit alpha
//! two columns wide (generated by `tools/gen_hangul.py`).

mod data;
mod hangul;
pub use data::{BODY, HUGE, SMALL, TITLE};

use bp_hal::{Canvas, Rgb};

pub struct Font {
    pub width: u16,
    pub height: u16,
    pub baseline: u16,
    pub first: u8,
    pub last: u8,
    pub glyph_stride: usize,
    pub data: &'static [u8],
    /// Double-width glyphs for the non-ASCII characters the UI uses.
    pub wide: Option<&'static Wide>,
}

/// Double-width 2-bit-alpha glyphs, sorted by code point. Each glyph is
/// `width` x `height` pixels (width = two ASCII columns), four pixels per
/// byte, high bits first.
pub struct Wide {
    pub width: u16,
    pub height: u16,
    pub glyph_stride: usize,
    pub chars: &'static [u32],
    pub data: &'static [u8],
}

impl Wide {
    fn index(&self, ch: char) -> Option<usize> {
        self.chars.binary_search(&(ch as u32)).ok()
    }
}

/// Columns a character occupies: ASCII is one, everything else two.
pub fn cells(ch: char) -> usize {
    if ch.is_ascii() {
        1
    } else {
        2
    }
}

/// Columns `text` occupies.
pub fn text_cells(text: &str) -> usize {
    text.chars().map(cells).sum()
}

/// Split off the first line of `text` that fits in `max` columns, breaking
/// at a space when possible (a longer word is cut). Returns the line and the
/// rest with its leading spaces removed. A `\n` always ends the line.
pub fn split_line(text: &str, max: usize) -> (&str, &str) {
    let mut used = 0;
    let mut last_space = None;
    for (i, ch) in text.char_indices() {
        if ch == '\n' {
            return (&text[..i], &text[i + 1..]);
        }
        if ch == ' ' {
            last_space = Some(i);
        }
        used += cells(ch);
        if used > max {
            let cut = match last_space {
                Some(sp) if sp > 0 => sp,
                _ if i == 0 => ch.len_utf8(),
                _ => i,
            };
            return (text[..cut].trim_end(), text[cut..].trim_start_matches(' '));
        }
    }
    (text, "")
}

impl Font {
    /// Width in pixels of `text` (non-ASCII characters are two columns).
    pub fn text_width(&self, text: &str) -> i32 {
        text_cells(text) as i32 * self.width as i32
    }

    /// Whether `ch` has a real glyph (otherwise it draws as '?' or a box).
    pub fn has_glyph(&self, ch: char) -> bool {
        let code = ch as u32;
        if ch.is_ascii() {
            return code >= self.first as u32 && code <= self.last as u32;
        }
        self.wide.is_some_and(|w| w.index(ch).is_some())
    }

    /// Draw one glyph with its top-left at (x, y). Unknown ASCII renders as
    /// '?', unknown wide characters as an empty box two columns wide.
    pub fn draw_char(&self, c: &mut dyn Canvas, x: i32, y: i32, ch: char, color: Rgb) {
        if !ch.is_ascii() {
            self.draw_wide(c, x, y, ch, color);
            return;
        }
        let code = ch as u32;
        let idx = if code >= self.first as u32 && code <= self.last as u32 {
            (code - self.first as u32) as usize
        } else {
            (b'?' - self.first) as usize
        };
        let base = idx * self.glyph_stride;
        let (w, h) = (self.width as usize, self.height as usize);
        for py in 0..h {
            for px in 0..w {
                let n = py * w + px;
                let byte = self.data[base + n / 2];
                let nib = if n % 2 == 0 { byte >> 4 } else { byte & 0x0F };
                if nib != 0 {
                    c.blend_pixel(x + px as i32, y + py as i32, color, nib * 17);
                }
            }
        }
    }

    fn draw_wide(&self, c: &mut dyn Canvas, x: i32, y: i32, ch: char, color: Rgb) {
        let found = self.wide.and_then(|w| w.index(ch).map(|i| (w, i)));
        let Some((wide, idx)) = found else {
            // missing glyph: a hollow box so it is never silently dropped
            let (w, h) = (2 * self.width as i32, self.height as i32);
            let (l, r, t, b) = (x + 2, x + w - 3, y + h / 5, y + h - h / 5);
            for px in l..=r {
                c.blend_pixel(px, t, color, 255);
                c.blend_pixel(px, b, color, 255);
            }
            for py in t..=b {
                c.blend_pixel(l, py, color, 255);
                c.blend_pixel(r, py, color, 255);
            }
            return;
        };
        let base = idx * wide.glyph_stride;
        let (w, h) = (wide.width as usize, wide.height as usize);
        for py in 0..h {
            for px in 0..w {
                let n = py * w + px;
                let v = (wide.data[base + n / 4] >> (6 - 2 * (n % 4))) & 3;
                if v != 0 {
                    c.blend_pixel(x + px as i32, y + py as i32, color, v * 85);
                }
            }
        }
    }

    /// Draw a string with its top-left at (x, y). Returns the x after the text.
    pub fn draw(&self, c: &mut dyn Canvas, x: i32, y: i32, text: &str, color: Rgb) -> i32 {
        let mut cx = x;
        for ch in text.chars() {
            self.draw_char(c, cx, y, ch, color);
            cx += cells(ch) as i32 * self.width as i32;
        }
        #[cfg(feature = "layout-check")]
        assert!(
            text.is_empty()
                || (x >= 0 && cx <= c.width() as i32 && y + self.height as i32 <= c.height() as i32),
            "text off screen: {text:?} at ({x}, {y}) to x={cx}"
        );
        cx
    }

    /// Draw `text` wrapped to `max_w` pixels, at most `max_lines` lines
    /// (`line_h` apart); the last line ends in "..." if text remains.
    /// Returns the y below the last line drawn.
    #[allow(clippy::too_many_arguments)]
    pub fn draw_wrapped(
        &self,
        c: &mut dyn Canvas,
        x: i32,
        y: i32,
        max_w: i32,
        line_h: i32,
        max_lines: usize,
        text: &str,
        color: Rgb,
    ) -> i32 {
        let max = (max_w / self.width as i32).max(4) as usize;
        let (mut rest, mut y) = (text, y);
        for n in 0..max_lines {
            if rest.is_empty() {
                break;
            }
            let (line, tail) = split_line(rest, max);
            if n + 1 == max_lines && !tail.is_empty() {
                let (short, _) = split_line(line, max - 3);
                let end = self.draw(c, x, y, short, color);
                self.draw(c, end, y, "...", color);
            } else {
                self.draw(c, x, y, line, color);
            }
            rest = tail;
            y += line_h;
        }
        y
    }

    /// Draw text horizontally centred in [x, x+w).
    pub fn draw_centered(&self, c: &mut dyn Canvas, x: i32, w: i32, y: i32, text: &str, color: Rgb) {
        let tw = self.text_width(text);
        self.draw(c, x + (w - tw) / 2, y, text, color);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn split_line_counts_wide_characters_as_two_columns() {
        assert_eq!(split_line("one two three", 7), ("one two", "three"));
        assert_eq!(split_line("one two", 7), ("one two", ""));
        assert_eq!(split_line("abcdefghij", 4), ("abcd", "efghij"));
        assert_eq!(split_line("a\nb", 9), ("a", "b"));
        assert_eq!(split_line("가나 다라마", 6), ("가나", "다라마"));
        assert_eq!(split_line("가나다라", 5), ("가나", "다라"));
        assert_eq!(split_line("가", 1), ("가", ""));
        assert_eq!(text_cells("a가b"), 4);
    }
}
